CustomField.formula:
IF( ISPICKVAL(Status__c, "Closed") && ISPICKVAL(Closed__c, "Won"), "Closed Won",
			IF( ISPICKVAL(Status__c, "Closed") && ISPICKVAL(Closed__c, "Lost"), "Closed Lost",
						IF(ISPICKVAL(Status__c, "Draft"),"Draft",IF(ISPICKVAL(Status__c, "Proposal"),"Proposal",
																																																		IF(ISPICKVAL(Status__c, "Approval"),"Approval",IF(ISPICKVAL(Status__c, "Ready to close"),"Ready to close","Cancel"
						)
			)
)
)
																																																																																		)
		)
